  "Хан-Уул дүүрэг, Намуун төгөл хотхон, 8Б": {"mn":"Хан-Уул дүүрэг, Намуун төгөл хотхон, 8Б","en":"Khan-Uul District, Namuun Tokkol Town, 8B","ko":"Khan-Uul District, Namuun Tokkol Town, 8B","ja":"カンオール地区、ナムウントッコルタウン、8B","zh":"Khan-Uul 区，Namuun Tokkol 镇，8B"},
